parameters.jsCode:
// Validate up front so a bad request fails here with a clear message, rather
// than as a confusing 400 from Cal.com three nodes later.
const b = $('Actions Webhook').item.json.body ?? {};
const action = String(b.action ?? '').toLowerCase();

if (!['book', 'cancel', 'reschedule'].includes(action)) {
  throw new Error(`action must be book|cancel|reschedule, got: ${b.action}`);
}
if (!b.session_id) throw new Error('session_id is required to tie the booking to a run');

if (action === 'book') {
  if (!b.start)          throw new Error('book requires start (ISO 8601, UTC)');
  if (!b.attendee?.email) throw new Error('book requires attendee.email');
} else {
  if (!b.booking_uid) throw new Error(`${action} requires booking_uid`);
  if (action === 'reschedule' && !b.start) throw new Error('reschedule requires the new start');
}

// Cal.com rejects a start that carries an offset -- it must be UTC with a Z.
let startUtc = null;
if (b.start) {
  const dt = DateTime.fromISO(b.start, { setZone: true });
  if (!dt.isValid) throw new Error(`Unparseable start: ${b.start}`);
  startUtc = dt.toUTC().toISO({ suppressMilliseconds: true });
}

return [{
  json: {
    action,
    sessionId:   b.session_id,
    bookingUid:  b.booking_uid ?? null,
    start:       startUtc,
    reason:      b.reason ?? '',
    attendee: {
      name:     b.attendee?.name  ?? 'Guest',
      email:    b.attendee?.email ?? '',
      timeZone: b.attendee?.timeZone || $env.MEETING_TIMEZONE || 'Asia/Karachi',
      language: b.attendee?.language ?? 'en',
    },
    eventTypeId:   b.event_type_id ?? null,
    eventTypeSlug: b.event_type_slug ?? $env.CAL_EVENT_TYPE_SLUG ?? null,
    username:      b.username ?? $env.CAL_USERNAME ?? null,
  },
}];

parameters.jsonBody:
={{ JSON.stringify(Object.assign({
  start: $('Validate Request').item.json.start,
  attendee: $('Validate Request').item.json.attendee,
  // metadata is how an inbound BOOKING_CREATED webhook finds the run.
  // Note Cal.com omits metadata from BOOKING_CANCELLED (calcom#27783),
  // which is why agent_runs also stores cal_booking_uid.
  metadata: { session_id: $('Validate Request').item.json.sessionId },
}, $('Validate Request').item.json.eventTypeId
     ? { eventTypeId: $('Validate Request').item.json.eventTypeId }
     : { eventTypeSlug: $('Validate Request').item.json.eventTypeSlug, username: $('Validate Request').item.json.username })) }}

={{ JSON.stringify({
  start: $('Validate Request').item.json.start,
  reschedulingReason: $('Validate Request').item.json.reason || 'Rescheduled via AI sales agent',
}) }}

parameters.jsCode:
// Cal wraps every response as { status, data }. Normalise the three actions
// into one shape so a single write-back node handles all of them.
const res  = $input.first().json;
const data = res.data ?? res;
const v    = $('Validate Request').item.json;

if (res.status && res.status !== 'success') {
  throw new Error(`Cal.com returned ${res.status}: ${JSON.stringify(res.error ?? {}).slice(0, 300)}`);
}

// A reschedule returns the NEW booking with a NEW uid. Store that, or the next
// cancel will 400 against a uid Cal.com has already marked cancelled.
const uid = data.uid ?? v.bookingUid;

return [{
  json: {
    action:     v.action,
    sessionId:  v.sessionId,
    uid,
    status:     v.action === 'cancel' ? 'cancelled' : (data.status ?? 'accepted'),
    start:      data.start ?? v.start,
    meetingUrl: data.meetingUrl ?? data.location ?? '',
    booked:     v.action !== 'cancel',
  },
}];

parameters.jsonBody:
={{ JSON.stringify({
  p_session_id: $json.sessionId,
  p_cal_booking_uid: $json.uid,
  p_cal_booking_status: $json.status,
  p_cal_meeting_url: $json.meetingUrl,
  p_meeting_start_at: $json.start,
  p_meeting_booked: $json.booked,
}) }}
